def _data_dir():
    """Per-user, per-OS data directory — the conventional spot on each platform."""
    if sys.platform == "darwin":
        base = Path.home() / "Library" / "Application Support"
    elif sys.platform == "win32":
        base = Path(os.environ.get("APPDATA") or Path.home())
    else:
        base = Path(os.environ.get("XDG_DATA_HOME") or (Path.home() / ".local" / "share"))
    path = base / "ResolutionStudio"
    path.mkdir(parents=True, exist_ok=True)
    return path


def _write_app_html():
    """Decode the bundled app and write it to a stable path.

    Using a real, fixed file:// location (rather than handing pywebview a
    raw HTML string) matters: it gives the page a stable origin, which is
    what lets its localStorage-based resolution storage actually persist
    between launches. A raw in-memory string would get treated as a
    null/blank origin and likely lose your data on every relaunch.
    """
    html_path = _data_dir() / "resolution-studio.html"
    content = base64.b64decode(_HTML_B64)
    html_path.write_bytes(content)
    return html_path


def main():
    html_path = _write_app_html()
    webview.create_window(
        "Resolution Studio",
        url=html_path.as_uri(),
        width=1360,
        height=900,
        min_size=(820, 560),
        background_color="#eef1f6",
    )
    webview.start()


if __name__ == "__main__":
    main()
